const body = $input.first().json.body ?? $input.first().json;
if (body.workflow !== 'bev-navigator') throw new Error('Wrong workflow');
const stage = body.stage === 'mid' ? 'mid' : body.stage === 'final' ? 'final' : null;
if (!stage) throw new Error('Bad stage');
const clientSession = String(body.clientSession ?? '');
if (!/^[0-9a-f-]{16,80}$/i.test(clientSession)) throw new Error('Bad session');
const situations = ['urbanRenter','familyHome','distance','cost','skeptic','occasional'];
const classify = (body.nodes ?? []).find((n) => n.id === 'classify');
const situation = classify?.output?.situation ?? null;
if (situation != null && !situations.includes(situation)) throw new Error('Bad situation');
const price = (body.nodes ?? []).find((n) => n.id === 'price')?.output ?? {};
function money(n) {
  const x = Number(n);
  if (!Number.isFinite(x)) return 0;
  return Math.max(-500000, Math.min(500000, Math.round(x)));
}
const togglesIn = (body.nodes ?? []).find((n) => n.id === 'solutions')?.output ?? {};
const allowed = ['home','work','rightSize','used','publicPlan','tariff','pv','insDiscount'];
const toggles = {};
for (const key of allowed) toggles[key] = Boolean(togglesIn[key]);
const id = crypto.randomUUID();
return [{
  json: {
    id,
    clientSession,
    stage,
    payload: {
      workflow: 'bev-navigator',
      stage,
      clientSession,
      situation,
      confidence: Math.max(0, Math.min(1, Number(classify?.output?.confidence) || 0)),
      price: {
        annualKeep: money(price.annualKeep),
        annualSwap: money(price.annualSwap),
        cash: money(price.cash),
        saving: money(price.saving),
        paybackYears: price.paybackYears == null || !Number.isFinite(Number(price.paybackYears)) ? null : Math.round(Number(price.paybackYears) * 10) / 10,
        withinHorizon: Boolean(price.withinHorizon),
        dataset: 'placeholder-2026-10-02',
        homeSource: typeof price.homeSource === 'string' ? price.homeSource.slice(0, 80) : 'placeholder',
        canton: price.canton ?? null
      },
      toggles,
      claimsOpened: Array.isArray(body.claimsOpened) ? body.claimsOpened.slice(0, 12) : [],
      answers: body.answers ?? {}
    }
  }
}];

const row = $input.first().json;
// Francs were computed in the browser. This node checks they arrived and does not replace them.
if (!row.payload || !row.payload.price) throw new Error('Missing price');
return [{ json: row }];

const row = $input.first().json;
const keys = ['home','work','rightSize','used','publicPlan','tariff','pv','insDiscount'];
for (const key of Object.keys(row.payload.toggles)) {
  if (!keys.includes(key)) throw new Error('Unexpected switch');
}
return [{ json: row }];
